mapper.insert:
INSERT INTO resident_locations (resident_id, location_id, start_date, end_date)
SELECT #{residentId}, #{locationId}, #{startDate}, #{endDate}
WHERE NOT EXISTS (
    SELECT 1 FROM resident_locations
    WHERE resident_id = #{residentId}
        AND (end_date IS NULL OR end_date > NOW())
)

mapper.select:
SELECT resident_id, location_id, start_date, end_date
FROM resident_locations
WHERE resident_id = #{residentId}
    AND location_id = #{locationId}
    AND (end_date IS NULL OR end_date > NOW())

SELECT EXISTS (
    SELECT 1
    FROM resident_locations
    WHERE location_id = #{locationId}
        AND (end_date IS NULL OR end_date > NOW())
)

mapper.update:
UPDATE resident_locations SET end_date = NOW()
WHERE resident_id = #{residentId}
    AND location_id = #{locationId}
    AND (end_date IS NULL OR end_date > NOW())
